-- DailyEng — seed nhóm "hoc-thuat". SINH TỰ ĐỘNG bởi scripts/generate-decks.mts, đừng sửa tay.
-- Chạy SAU schema-07-nhom-bo-tu.sql. Chạy lại nhiều lần được: bộ đã có thì cập nhật tên/mô tả,
-- từ đã có (deck_id, term) thì giữ nguyên để không mất tiến độ học của người dùng.

-- Nghiên cứu & phương pháp (100 từ)
insert into public.decks (slug, name, description, level, category, position)
values ('hoc-thuat-nghien-cuu', 'Nghiên cứu & phương pháp', 'Giả thuyết, dữ liệu, phân tích, kết luận', 'advanced', 'hoc-thuat', 10)
on conflict (slug) do update set
  name = excluded.name, description = excluded.description, level = excluded.level,
  category = excluded.category, position = excluded.position;

insert into public.words (deck_id, term, phonetic, meaning_vi, example_en, example_vi, position)
select d.id, w.term, w.phonetic, w.meaning_vi, w.example_en, w.example_vi, w.position
from public.decks d
join (values
  ('research', '/rɪˈsɜːtʃ/', 'nghiên cứu (n, v)', 'Her research focuses on renewable energy.', 'Nghiên cứu của cô ấy tập trung vào năng lượng tái tạo.', 1),
  ('hypothesis', '/haɪˈpɒθəsɪs/', 'giả thuyết (n)', 'The data did not support the hypothesis.', 'Dữ liệu không ủng hộ giả thuyết.', 2),
  ('methodology', '/ˌmeθəˈdɒlədʒi/', 'phương pháp luận (n)', 'The methodology is described in chapter three.', 'Phương pháp luận được mô tả ở chương ba.', 3),
  ('method', '/ˈmeθəd/', 'phương pháp (n)', 'We used a mixed-methods approach.', 'Chúng tôi dùng cách tiếp cận hỗn hợp phương pháp.', 4),
  ('approach', '/əˈprəʊtʃ/', 'cách tiếp cận (n)', 'A qualitative approach was adopted.', 'Cách tiếp cận định tính đã được áp dụng.', 5),
  ('data', '/ˈdeɪtə/', 'dữ liệu (n)', 'The data were collected over six months.', 'Dữ liệu được thu thập trong sáu tháng.', 6),
