  ('survey', '/ˈsɜːveɪ/', 'khảo sát (n, v)', 'The survey was conducted online.', 'Khảo sát được thực hiện trực tuyến.', 10),
  ('questionnaire', '/ˌkwestʃəˈneə/', 'bảng câu hỏi (n)', 'The questionnaire had 25 items.', 'Bảng câu hỏi có 25 mục.', 11),
  ('interview', '/ˈɪntəvjuː/', 'phỏng vấn (n, v)', 'We interviewed ten teachers.', 'Chúng tôi phỏng vấn mười giáo viên.', 12),
  ('experiment', '/ɪkˈsperɪmənt/', 'thí nghiệm (n)', 'The experiment was repeated three times.', 'Thí nghiệm được lặp lại ba lần.', 13),
  ('observation', '/ˌɒbzəˈveɪʃn/', 'quan sát (n)', 'Classroom observations lasted two weeks.', 'Quan sát lớp học kéo dài hai tuần.', 14),
  ('variable', '/ˈveəriəbl/', 'biến số (n)', 'Age was treated as a control variable.', 'Tuổi được xem là biến kiểm soát.', 15),
  ('independent variable', '/ˌɪndɪˈpendənt ˈveəriəbl/', 'biến độc lập (n)', 'The independent variable was study time.', 'Biến độc lập là thời gian học.', 16),
  ('dependent variable', '/dɪˈpendənt ˈveəriəbl/', 'biến phụ thuộc (n)', 'Test scores were the dependent variable.', 'Điểm bài kiểm tra là biến phụ thuộc.', 17),
  ('control group', '/kənˈtrəʊl ɡruːp/', 'nhóm đối chứng (n)', 'The control group received no training.', 'Nhóm đối chứng không được huấn luyện.', 18),
  ('analysis', '/əˈnæləsɪs/', 'phân tích (n)', 'Statistical analysis revealed a strong link.', 'Phân tích thống kê cho thấy mối liên hệ mạnh.', 19),
