  ('conclude', '/kənˈkluːd/', 'kết luận (v)', 'We conclude that the method is effective.', 'Chúng tôi kết luận phương pháp này hiệu quả.', 25),
  ('literature review', '/ˈlɪtrətʃə rɪˈvjuː/', 'tổng quan tài liệu (n)', 'The literature review covers 50 studies.', 'Tổng quan tài liệu bao quát 50 nghiên cứu.', 26),
  ('citation', '/saɪˈteɪʃn/', 'trích dẫn (n)', 'Every claim needs a citation.', 'Mọi khẳng định đều cần trích dẫn.', 27),
