-- Lập luận & phản biện (100 từ)
insert into public.decks (slug, name, description, level, category, position)
values ('hoc-thuat-lap-luan', 'Lập luận & phản biện', 'Từ nối, quan điểm, đánh giá, IELTS Writing', 'advanced', 'hoc-thuat', 20)
on conflict (slug) do update set
  name = excluded.name, description = excluded.description, level = excluded.level,
  category = excluded.category, position = excluded.position;

insert into public.words (deck_id, term, phonetic, meaning_vi, example_en, example_vi, position)
select d.id, w.term, w.phonetic, w.meaning_vi, w.example_en, w.example_vi, w.position
from public.decks d
join (values
  ('argument', '/ˈɑːɡjumənt/', 'luận điểm, lập luận (n)', 'The essay presents a clear argument.', 'Bài luận trình bày một lập luận rõ ràng.', 1),
  ('argue', '/ˈɑːɡjuː/', 'lập luận, cho rằng (v)', 'Some argue that tests are unfair.', 'Một số người cho rằng các kỳ thi không công bằng.', 2),
  ('claim', '/kleɪm/', 'khẳng định (n, v)', 'This claim is not supported by facts.', 'Khẳng định này không có dữ kiện ủng hộ.', 3),
  ('opinion', '/əˈpɪnjən/', 'ý kiến (n)', 'In my opinion, the policy works.', 'Theo ý tôi, chính sách này hiệu quả.', 4),
  ('viewpoint', '/ˈvjuːpɔɪnt/', 'quan điểm (n)', 'Both viewpoints deserve attention.', 'Cả hai quan điểm đều đáng chú ý.', 5),
  ('perspective', '/pəˈspektɪv/', 'góc nhìn (n)', 'From an economic perspective, it makes sense.', 'Từ góc nhìn kinh tế, điều đó hợp lý.', 6),
